<style>
  :root{
    --black:#101010;
    --white:#fafaf5;
    --red:#d62828;
    --blue:#19418c;
    --yellow:#f0c020;
    --gap:clamp(8px, 1.1vw, 14px);
  }
  *{ box-sizing:border-box; }
  html, body{ margin:0; }
  body{
    background:var(--white);
    color:var(--black);
    font-family:"Archivo", system-ui, "Segoe UI", sans-serif;
    -webkit-font-smoothing:antialiased;
    text-rendering:optimizeLegibility;
  }
  .wrap{
    max-width:1240px;
    margin:0 auto;
    padding:var(--gap);
  }

  /* The page is a Mondrian: black grid lines (the grid's background),
     white ground, red / blue / yellow blocks placed like the painting. */
  .grid{
    display:grid;
    background:var(--black);
    gap:var(--gap);
    padding:var(--gap);
    grid-template-columns:1fr 1.5fr 1.5fr 1.2fr 1.2fr;
    grid-template-areas:
      "head head head red  red"
      "head head head red  red"
      "facts facts facts stage stage"
      "facts facts facts stage stage"
      "why   why   why   stage stage"
      "why   why   why   stage stage"
      "blue  cta   cta   cta   yellow";
    grid-template-rows:auto auto auto auto auto auto 176px;
  }
  .cell{ background:var(--white); min-width:0; }

  /* ---- head ---- */
  .head{
    grid-area:head;
    display:flex;
    flex-direction:column;
    justify-content:center;
    padding:clamp(18px, 2.6vw, 40px);
  }
  .overline{
    margin:0 0 14px;
    font-size:13px;
    font-weight:700;
    letter-spacing:.22em;
    text-transform:uppercase;
  }
  .overline .dot{ color:var(--red); }
  h1{
    margin:0;
    font-size:clamp(34px, 4.6vw, 68px);
    font-weight:900;
    line-height:.98;
    letter-spacing:-.015em;
    text-transform:uppercase;
  }
  h1 .t-red{ color:var(--red); }
  h1 .t-blue{ color:var(--blue); }
  h1 .t-yellow{ color:#c79a12; }
  .meta{
    margin:18px 0 0;
    display:flex;
    flex-wrap:wrap;
    gap:8px 14px;
    font-size:15px;
    font-weight:500;
  }
  .meta span::before{ content:"—"; margin-right:14px; color:var(--black); opacity:.45; }
  .meta span:first-child::before{ content:""; margin:0; }
  .alt-title{
    margin:10px 0 0;
    font-size:13.5px;
    color:rgba(16,16,16,.62);
  }

  /* ---- pure colour blocks, like the painting ---- */
  .red-block{
    grid-area:red;
    background:var(--red);
    aspect-ratio:1/1;
    min-height:100%;
  }
  .blue-block{ grid-area:blue; background:var(--blue); aspect-ratio:1/1; }
  .yellow-block{ grid-area:yellow; background:var(--yellow); }

